  "content": "package com.skillforge.platform.service;

import com.skillforge.platform.entity.SkillPackage;
import com.skillforge.platform.entity.User;
import com.skillforge.platform.repository.SkillPackageRepository;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

@Service
public class PackageService {

    private static final String[] METADATA_KEYS = {"name", "version", "description", "author", "category"};

    private final SkillPackageRepository skillPackageRepository;

    @Value("${skillforge.upload.dir}")
    private String uploadDir;

    public PackageService(SkillPackageRepository skillPackageRepository) {
        this.skillPackageRepository = skillPackageRepository;
    }

    public SkillPackage upload(MultipartFile file, User user) {
        try {
            Path dir = Paths.get(uploadDir);
            Files.createDirectories(dir);
            String storedName = UUID.randomUUID().toString() + ".zip";
            Path target = dir.resolve(storedName);
            Files.write(target, file.getBytes());
            SkillPackage skillPackage = SkillPackage.builder()
                    .userId(user.getId())
                    .status("UPLOADED")
                    .uploadPath(target.toString())
                    .originalFilename(file.getOriginalFilename())
                    .createdAt(LocalDateTime.now())
                    .build();
            return skillPackageRepository.save(skillPackage);
        } catch (IOException e) {
            throw new RuntimeException("Failed to store uploaded file", e);
        }
    }

    public SkillPackage parse(Long id, User user) {
        SkillPackage skillPackage = skillPackageRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Package not found"));
        if (!skillPackage.getUserId().equals(user.getId())) {
            throw new RuntimeException("Access denied");
        }
        try {
            String content = readSkillMd(skillPackage.getUploadPath());
            String frontmatter = extractFrontmatter(content);
            if (frontmatter == null) {
                throw new IllegalStateException("No frontmatter found in SKILL.md");
            }
            Yaml yaml = new Yaml(new SafeConstructor());
            Object parsed = yaml.load(frontmatter);
            if (!(parsed instanceof Map)) {
                throw new IllegalStateException("Frontmatter is not a YAML map");
            }
            Map<?, ?> metadata = (Map<?, ?>) parsed;
            String[] values = new String[METADATA_KEYS.length];
            for (int i = 0; i < METADATA_KEYS.length; i++) {
                values[i] = stringValue(metadata, METADATA_KEYS[i]);
            }
            skillPackage.setName(values[0]);
            skillPackage.setVersion(values[1]);
            skillPackage.setDescription(values[2]);
            skillPackage.setAuthor(values[3]);
            skillPackage.setCategory(values[4]);
            skillPackage.setStatus("PARSED");
            skillPackage.setParsedAt(LocalDateTime.now());
        } catch (Exception e) {
            skillPackage.setStatus("PARSE_FAILED");
        }
        return skillPackageRepository.save(skillPackage);
    }

    public List<SkillPackage> listPackages(User user) {
        return skillPackageRepository.findByUserIdOrderByCreatedAtDesc(user.getId());
    }

    public SkillPackage getPackage(Long id, User user) {
        SkillPackage skillPackage = skillPackageRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Package not found"));
        if (!skillPackage.getUserId().equals(user.getId())) {
            throw new RuntimeException("Access denied");
        }
        return skillPackage;
    }

    private String readSkillMd(String uploadPath) throws IOException {
        try (InputStream in = Files.newInputStream(Paths.get(uploadPath));
             ZipInputStream zis = new ZipInputStream(in)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                if ("SKILL.md".equals(entry.getName())) {
                    ByteArrayOutputStream out = new ByteArrayOutputStream();
                    byte[] buffer = new byte[4096];
                    int read;
                    while ((read = zis.read(buffer)) != -1) {
                        out.write(buffer, 0, read);
                    }
                    return new String(out.toByteArray(), StandardCharsets.UTF_8);
                }
            }
        }
        throw new IOException("SKILL.md entry not found in archive");
    }

    private String extractFrontmatter(String content) {
        String[] lines = content.split("\n");
        if (lines.length == 0 || !lines[0].trim().equals("---")) {
            return null;
        }
        StringBuilder frontmatter = new StringBuilder();
        for (int i = 1; i < lines.length; i++) {
            if (lines[i].trim().equals("---")) {
                return frontmatter.toString();
            }
            frontmatter.append(lines[i]).append("\n");
        }
        return null;
    }

    private String stringValue(Map<?, ?> metadata, String key) {
        Object value = metadata.get(key);
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            throw new IllegalStateException("Metadata value for '" + key + "' is not a string");
        }
        return (String) value;
    }
}
